//! `kind = "ts-program"` without hand-written PIDs: stream roles and the
//! PID plan (`pid_map = "auto"`), program selection in multi-program
//! recordings (`program` / `service_id` / `service_name`, ambiguity and
//! not-found errors listing the programs), explicit `pid_map` validation
//! against the source PMT, and the TOML-free template
//! (`relay_template::RelayOptions`) against `examples/relay-ts.toml`.
//!
//! Sources are generated by this crate: services with permuted PIDs, two
//! audio streams, caption / superimpose PES (ARIB data_component_id 0x0008)
//! injected into null slots — synchronous PES (stream_id 0xBD, PTS) and
//! asynchronous PES (0xBF, no PTS) — and a carousel.

mod common;

use arib_analyze::scan::{ScanOptions, scan_packets};
use arib_analyze::validate::{Severity, ValidateOptions, validate};
use arib_mux::relay::{self, Role};
use arib_mux::relay_template::RelayOptions;
use arib_mux::{Config, Multiplexer, Packet};
use arib_ts::pcr::BASE_MODULUS;
use common::{bench_params, synth_audio, synth_video, tmpdir};
use std::path::{Path, PathBuf};

fn pid(p: &Packet) -> u16 {
    (u16::from(p[1] & 0x1F) << 8) | u16::from(p[2])
}

fn payload(p: &Packet) -> &[u8] {
    let afc = (p[3] >> 4) & 3;
    let s = if afc & 2 != 0 { 5 + p[4] as usize } else { 4 };
    &p[s.min(188)..]
}

/// One-packet PES of 184 bytes: synchronous (stream_id 0xBD, PTS) or
/// asynchronous (0xBF, no PTS) with a counter in the data bytes.
fn private_pes(pid: u16, cc: u8, pts: Option<u64>, n: u32) -> Packet {
    let mut p = [0xFFu8; 188];
    p[0] = 0x47;
    p[1] = 0x40 | (pid >> 8) as u8;
    p[2] = pid as u8;
    p[3] = 0x10 | (cc & 0x0F);
    let pes = &mut p[4..];
    pes[..3].copy_from_slice(&[0, 0, 1]);
    pes[4..6].copy_from_slice(&178u16.to_be_bytes()); // 6 + 178 = 184
    let data = match pts {
        Some(v) => {
            pes[3] = 0xBD;
            pes[6..9].copy_from_slice(&[0x80, 0x80, 5]);
            let v = v % BASE_MODULUS;
            pes[9] = 0x21 | (((v >> 30) as u8 & 7) << 1);
            pes[10] = (v >> 22) as u8;
            pes[11] = 0x01 | ((v >> 15) as u8) << 1;
            pes[12] = (v >> 7) as u8;
            pes[13] = 0x01 | (v as u8) << 1;
            14
        }
        None => {
            pes[3] = 0xBF;
            6
        }
    };
    pes[data] = 0x80; // data_group_id-like first byte
    pes[data + 1..data + 5].copy_from_slice(&n.to_be_bytes());
    p
}

/// Private PES injected into the source: (PID, synchronous?).
type Inject = (u16, bool);

/// Source TS (multiplex-frame TS) from a service section of TOML, with
/// one private PES per `inject` PID every ≈ 0.5 s in null slots.
fn source(dir: &Path, name: &str, services: &str, inject: &[Inject], seconds: f64) -> PathBuf {
    std::fs::write(dir.join("v.m2v"), synth_video(6)).unwrap();
    std::fs::write(dir.join("a.adts"), synth_audio(122)).unwrap();
    std::fs::write(dir.join("a2.adts"), synth_audio(122)).unwrap();
    let text = format!(
        r#"
[network]
network_id = 0x0004
name = "BSデジタル"
area_code = 0x5A5
remote_control_key_id = 1
channels = [27]

[transport]
transport_stream_id = 0x4090

[clock]
source = "fixed"
start = "2026-10-08T11:59:50"
{services}
"#
    );
    let cfg = Config::from_toml(&text).unwrap();
    let p = bench_params();
    let mut mux = Multiplexer::new(&cfg, &p, dir).unwrap();
    let frames = (seconds / p.frame_seconds()).ceil() as u64;
    let mut out = Vec::new();
    let mut next = vec![0u64; inject.len()];
    let mut cc = vec![0u8; inject.len()];
    let mut n = 0u32;
    for k in 0..frames {
        let (full, _) = mux.next_frame_full();
        for (j, mut pk) in full.into_iter().enumerate() {
            let t = mux.slot_time(k, j);
            if pid(&pk) == 0x1FFF
                && let Some(i) = (0..inject.len()).find(|&i| t >= next[i])
            {
                let (ipid, sync) = inject[i];
                pk = private_pes(ipid, cc[i], sync.then(|| t / 300 + 27_000), n);
                cc[i] = cc[i].wrapping_add(1);
                next[i] = t + 13_500_000;
                n += 1;
            }
            out.extend_from_slice(&pk);
        }
    }
    let path = dir.join(name);
    std::fs::write(&path, out).unwrap();
    path
}

/// Relay configuration text around one `ts-program` stream (no pid_map).
fn relay_text(src: &Path, extra: &str) -> String {
    format!(
        r#"
[network]
network_id = 0x7FE0
name = "ベンチ"
area_code = 0x8D5
remote_control_key_id = 9
channels = [44]

[transport]
transport_stream_id = 0x7FE0

[clock]
source = "fixed"
start = "2026-10-09T09:00:00"

[[service]]
service_id = 0x0400
name = "再送信"
layer = "B"
pmt_pid = 0x01F0
pcr_pid = 0x01FF

  [[service.stream]]
  kind = "ts-program"
  source = "{}"
{extra}
"#,
        src.display()
    )
}

fn relay_cfg(src: &Path, extra: &str) -> Config {
    Config::from_toml(&relay_text(src, extra)).unwrap()
}

fn probe(src: &Path, extra: &str) -> arib_mux::Result<relay::Probe> {
    let cfg = relay_cfg(src, extra);
    relay::probe(src, &cfg.services[0].streams[0])
}

