#[test]
fn program_selection_in_multi_program_recordings() {
    let dir = tmpdir("relay-programs");
    let src = source(
        &dir,
        "three.ts",
        &format!("{PROGRAM_A}{PROGRAM_B}{DATA_ONLY}"),
        &[],
        3.0,
    );
    // no selection: ambiguous, every program listed with name and streams
    let e = probe(&src, "").unwrap_err().to_string();
    for want in [
        "the recording has 3 programs (2 with elementary-stream packets)",
        "0x00d3 \"ソースＡ\" (service_type 0x01, PMT 0x0101): video 0x0140 (0x02), audio 0x0141 (0x0f)",
        "0x00d4 \"ソースＢ\" (service_type 0x01, PMT 0x0102): video 0x0240 (0x02), audio 0x0241 (0x0f)",
        "0x00d5 \"データ\" (service_type 0xc0, PMT 0x0103): data carousel 0x0340 (0x0d); 0 ES packets",
        "--program / --service-name",
    ] {
        assert!(e.contains(want), "missing {want:?} in\n{e}");
    }
    // by number, by service_id (alias), by SDT name (full-width folded)
    for (extra, how) in [
        ("  program = 0x00D4", "program given"),
        ("  service_id = 0x00D4", "program given"),
        ("  service_name = \"ソースＢ\"", "matches the SDT"),
        ("  service_name = \"ｿｰｽＢ\"", ""), // half-width katakana is not folded
    ] {
        let r = probe(&src, extra);
        if how.is_empty() {
            assert!(
                r.unwrap_err()
                    .to_string()
                    .contains("matches no SDT service")
            );
            continue;
        }
        let p = r.unwrap();
        assert_eq!(p.program, 0x00D4, "{extra}");
        assert!(p.chosen_by.contains(how), "{}", p.chosen_by);
        assert_eq!(p.service_name.as_deref(), Some("ソースＢ"));
        let m: Vec<(u16, u16)> = p.es.iter().map(|e| (e.src_pid, e.pid)).collect();
        assert_eq!(m, vec![(0x0240, 0x0111), (0x0241, 0x0112)]);
        assert!(
            p.report()
                .contains("dropped PID 0x0140: elementary stream of program 0x00d3"),
            "{}",
            p.report()
        );
    }
    let e = probe(&src, "  service_name = \"ソース\"")
        .unwrap_err()
        .to_string();
    assert!(e.contains("is ambiguous (2 programs match)"), "{e}");
    let e = probe(&src, "  program = 0x0999").unwrap_err().to_string();
    assert!(
        e.contains("program 0x0999 is not in the PAT") && e.contains("0x00d4 \"ソースＢ\""),
        "{e}"
    );
    let e = Config::from_toml(&relay_text(&src, "  program = 1\n  service_name = \"x\""))
        .unwrap_err()
        .to_string();
    assert!(e.contains("give one"), "{e}");

    // one program with packets + a data-only one: the former is taken
    let src2 = source(
        &dir,
        "one-live.ts",
        &format!("{PROGRAM_A}{DATA_ONLY}"),
        &[],
        3.0,
    );
    let p = probe(&src2, "").unwrap();
    assert_eq!(p.program, 0x00D3);
    assert_eq!(
        p.chosen_by,
        "the only program whose elementary streams carry packets"
    );
}

#[test]
fn explicit_pid_map_and_plan_overrides_are_checked() {
    let dir = tmpdir("relay-pidmap");
    let src = source(&dir, "permuted.ts", PERMUTED, &[], 3.0);
    // not an elementary stream of the program
    let e = probe(&src, "  pid_map = [[0x0999, 0x0111]]")
        .unwrap_err()
        .to_string();
    assert!(
        e.contains("pid_map [0x0999, 0x0111]: 0x0999 is not an elementary stream of program 0x00d3 (its PMT lists 0x0200 (stream_type 0x0f), 0x0901"),
        "{e}"
    );
    // an elementary stream that is not relayed
    let e = probe(&src, "  pid_map = [[0x0150, 0x0150]]")
        .unwrap_err()
        .to_string();
    assert!(
        e.contains("source PID 0x0150 of program 0x00d3 is not relayed (section / carousel stream"),
        "{e}"
    );
    // unlisted streams keep their PID: a collision is refused
    let e = probe(&src, "  pid_map = [[0x0901, 0x0310]]")
        .unwrap_err()
        .to_string();
    assert!(e.contains("output PID 0x0310 used by source PIDs"), "{e}");
    // a valid list: listed renumbered, the rest kept
    let p = probe(&src, "  pid_map = [[0x0901, 0x0111], [0x0310, 0x0112]]").unwrap();
    let m: Vec<(u16, u16)> = p.es.iter().map(|e| (e.src_pid, e.pid)).collect();
    assert_eq!(
        m,
        vec![
            (0x0200, 0x0200),
            (0x0901, 0x0111),
            (0x0310, 0x0112),
            (0x0777, 0x0777),
            (0x0123, 0x0123),
            (0x0124, 0x0124)
        ]
    );
    // "keep": the source PIDs
    let p = probe(&src, "  pid_map = \"keep\"").unwrap();
    assert!(p.es.iter().all(|e| e.pid == e.src_pid));
    // the plan overridden per role
    let p = probe(
        &src,
        "  pids = { video = 0x0100, audio = [0x0101, 0x0105], captions = 0x0200 }",
    )
    .unwrap();
    let m: Vec<(Role, usize, u16)> = p.es.iter().map(|e| (e.role, e.rank, e.pid)).collect();
    assert_eq!(
        m,
        vec![
            (Role::Audio, 1, 0x0105),
            (Role::Video, 0, 0x0100),
            (Role::Audio, 0, 0x0101),
            (Role::Captions, 0, 0x0200),
            (Role::Superimpose, 0, 0x0138),
            // no tag, no Timing and (in this source) no PES: caption assumed
            (Role::Captions, 1, 0x0201),
        ]
    );
    // configuration errors
    for (extra, want) in [
        (
            "  pid_map = [[0x0901, 0x0111]]\n  pids = { video = 0x0100 }",
            "applies only to pid_map = \"auto\"",
        ),
        (
            "  pids = { video = 0x0100, audio = 0x0100 }",
            "given to two roles",
        ),
        ("  pids = { video = 0x0005 }", "outside 0x0010–0x1FFE"),
        ("  pids = { video = [] }", "at least one PID"),
        ("  pids = { subtitles = 0x0130 }", "unknown field"),
        ("  pid_map = \"renumber\"", "\"auto\", \"keep\" or a list"),
        ("  pid_map = [[0x0901, 0x0111], [0x0901, 0x0112]]", "twice"),
    ] {
        let e = Config::from_toml(&relay_text(&src, extra))
            .unwrap_err()
            .to_string();
        assert!(e.contains(want), "{extra}: {e}");
    }
}

/// The template's defaults are the values of `examples/relay-ts.toml`
/// (apart from the names, which the template takes from one option).
#[test]
fn template_defaults_equal_the_example() {
    let ex = Config::from_toml(include_str!("../examples/relay-ts.toml")).unwrap();
    let source = ex.services[0].streams[0].source.clone().unwrap();
    let mut o = RelayOptions::new(&source);
    o.name = "ベンチ".into();
    let mut t = o.config().unwrap();
    // the example names its service "ベンチ録画"; the template uses one name
    t.services[0].name = ex.services[0].name.clone();
    assert_eq!(t.to_toml().unwrap(), ex.to_toml().unwrap());
}
